import '../styles/Cart.css';

function Cart({ cart, updateCart }) {
    let total = 0;
    for (let i = 0; i < cart.length; i++) {
        total += cart[i].price * cart[i].amount;
    }
    return (
        <div className='panel panel--cart'>
            <h2 className="panel__title">Panier</h2>
            <ul className="panel__list">
                {cart.map(({ name, price, amount }, index) => (
                    <li className="panel__item" key={`${name}-${index}`}>
                        <span>{name}</span>
                        <span>{price} x {amount}</span>
                    </li>
                ))}
            </ul>
            <div className="panel__total">
                Total : {total} €
            </div>
            <br />
            <button className="btn" onClick={() => updateCart([])}>
                Vider le panier
            </button>
        </div>
    );
}


export default Cart
